mapper.select:
/* PdaCommonPacoMapper.checkDuplicatePkgNo : 박스번호 중복 조회 */
SELECT PP.SEQ , PP.PACKING_NO , PP.DELETE_YN , IP.IN_PLAN_NO , IP.BL_NO , IP.AR_DATE , IP.VESSEL_FLIGHT , IP.MBL_NO , IP.OD_JOB_NO , IP.CARGO_REFERENCE_NO FROM TB_BMS_IN_PLAN_PKG PP WITH (NOLOCK) INNER JOIN TB_BMS_IN_PLAN IP WITH (NOLOCK) ON PP.IN_PLAN_NO = IP.IN_PLAN_NO WHERE PP.PACKING_NO = #{srchNo} AND PP.DELETE_YN !='Y'
ORDER BY IP.IN_PLAN_NO
